import{_ as i,c as e,o as a,ax as t}from"./chunks/framework.DHqKNX4U.js";const g=JSON.parse('{"title":"Startup Fails: \\"index row requires N bytes, maximum size is 8191\\"","description":"","frontmatter":{},"headers":[],"relativePath":"user-guides/troubleshooting/long-message-id.md","filePath":"user-guides/troubleshooting/long-message-id.md"}'),n={name:"user-guides/troubleshooting/long-message-id.md"};function h(l,s,r,p,o,d){return a(),e("div",null,s[0]||(s[0]=[t(`<h1 id="startup-fails-index-row-requires-n-bytes-maximum-size-is-8191" tabindex="-1">Startup Fails: &quot;index row requires N bytes, maximum size is 8191&quot; <a class="header-anchor" href="#startup-fails-index-row-requires-n-bytes-maximum-size-is-8191" aria-label="Permalink to &quot;Startup Fails: &quot;index row requires N bytes, maximum size is 8191&quot;&quot;">​</a></h1><p>This applies to a single, narrow case: upgrading an instance that ran <strong>v0.5.1</strong> and archived an email with an unusually long <code>Message-ID</code> header. On upgrade the application fails to start.</p><p>If you are already running v0.5.2 or later, this cannot affect you — see <a href="#why-only-v0-5-1">Why only v0.5.1</a> below.</p><h2 id="symptoms" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h2><p>The backend container exits during startup, and the logs end with a failed migration:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Running migrations...</span></span>
<span class="line"><span>Migration failed! error: index row requires 15744 bytes, maximum size is 8191</span></span></code></pre></div><p>The application never becomes available, and restarting produces the same error.</p><h2 id="root-cause" tabindex="-1">Root Cause <a class="header-anchor" href="#root-cause" aria-label="Permalink to &quot;Root Cause&quot;">​</a></h2><p><code>archived_emails.message_id_header</code> holds the <code>Message-ID</code> header exactly as the mail server sent it, and that header has no length limit in practice — a malformed or deliberately hostile message can carry one that runs to kilobytes.</p><p>v0.5.2 added an index over that column to speed up deduplication. PostgreSQL cannot index a value that large, so if your archive already contains one, building the index fails and the migration stops. Because migrations run at startup, the application stops with it.</p><p>Newer versions shorten these values as emails are archived, so no new row can trigger this. Rows written by v0.5.1, before the index existed, are the exception: they are already in the table when the index is built.</p><h2 id="solution" tabindex="-1">Solution <a class="header-anchor" href="#solution" aria-label="Permalink to &quot;Solution&quot;">​</a></h2><p>Shorten the affected values, then restart. The original headers are unaffected — they live in the archived <code>.eml</code> files, which are the record of what was received. The column being shortened is internal bookkeeping used to recognise an email the system has already seen.</p><ol><li><p><strong>Connect to your database.</strong> With the standard Docker Compose setup:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> psql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span></span></code></pre></div></li><li><p><strong>Check how many rows are affected.</strong> Usually a handful at most:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> archived_emails </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> octet_length(message_id_header) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 998</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></li><li><p><strong>Shorten them.</strong> This keeps the first 900 characters and appends a hash of the full value, so two different messages cannot end up sharing a key:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> archived_emails</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> message_id_header </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> left</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(message_id_header, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">900</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;-&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> md5(message_id_header)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> octet_length(message_id_header) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 998</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></li><li><p><strong>Repeat for the provider ID column</strong>, which stores the same header for IMAP and for file imports:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> archived_emails</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> provider_message_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> left</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(provider_message_id, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">900</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;-&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> md5(provider_message_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> octet_length(provider_message_id) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 998</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></li><li><p><strong>Restart.</strong> The migration re-runs from where it stopped and now completes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span></span></code></pre></div></li></ol><p>The affected emails stay in the archive and remain searchable. The only change is the internal key used to recognise them, so on the next sync each one may be archived a second time as a duplicate of itself. If that matters to you, note the <code>Message-ID</code> values before running the update.</p><h2 id="why-only-v0-5-1" tabindex="-1">Why only v0.5.1 <a class="header-anchor" href="#why-only-v0-5-1" aria-label="Permalink to &quot;Why only v0.5.1 {#why-only-v0-5-1}&quot;">​</a></h2><p>An instance that is running v0.5.2 or later has, by definition, already built this index successfully, which means no row large enough to break it was present. Any email that arrived afterwards with such a header was rejected at insert time and reported as a failed message rather than stored — so it is not in the table either.</p><p>That rejection was itself a bug (<a href="https://github.com/LogicLabs-OU/OpenArchiver/issues/440" target="_blank" rel="noreferrer">#440</a>): the email was counted as failed and the ingestion source went into an error state, but it was never archived and every retry failed the same way. Later versions shorten the value before storing it, so these emails are archived normally.</p>`,18)]))}const c=i(n,[["render",h]]);export{g as __pageData,c as default};
